function escapeHtml(value) {
    // Encode every HTML text/quoted-attribute delimiter before interpolation.
    return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

